#!/usr/bin/env python3
import fnmatch
import math
import os
import shutil
import struct
import subprocess
import sys
import time
from pathlib import Path

VERSION = "0.9.9"
AUTHOR = "Ajeet D'Souza <98ajeet@gmail.com>"
URL = "https://github.com/ajeetdsouza/zoxide"
SHELLS = ["bash", "elvish", "fish", "nushell", "posix", "powershell", "tcsh", "xonsh", "zsh"]
HOOKS = ["none", "prompt", "pwd"]
IMPORTS = ["autojump", "z"]
DB_VERSION = 3

ENV_BLOCK = """Environment variables:
  _ZO_DATA_DIR          Path for zoxide data files
  _ZO_ECHO              Print the matched directory before navigating to it when set to 1
  _ZO_EXCLUDE_DIRS      List of directory globs to be excluded
  _ZO_FZF_OPTS          Custom flags to pass to fzf
  _ZO_MAXAGE            Maximum total age after which entries start getting deleted
  _ZO_RESOLVE_SYMLINKS  Resolve symlinks when storing paths"""

MAIN_HELP = f"""zoxide {VERSION}
{AUTHOR}
{URL}

A smarter cd command for your terminal

Usage:
  executable <COMMAND>

Commands:
  add     Add a new directory or increment its rank
  edit    Edit the database
  import  Import entries from another application
  init    Generate shell configuration
  query   Search for a directory in the database
  remove  Remove a directory from the database

Options:
  -h, --help     Print help
  -V, --version  Print version

{ENV_BLOCK}"""

HELP = {
"add": f"""zoxide-add {VERSION}
{AUTHOR}
{URL}

Add a new directory or increment its rank

Usage:
  executable add [OPTIONS] <PATHS>...

Arguments:
  <PATHS>...  

Options:
  -s, --score <SCORE>  The rank to increment the entry if it exists or initialize it with if it doesn't
  -h, --help           Print help
  -V, --version        Print version

{ENV_BLOCK}""",
"edit": f"""zoxide-edit {VERSION}
{AUTHOR}
{URL}

Edit the database

Usage:
  executable edit

Options:
  -h, --help     Print help
  -V, --version  Print version

{ENV_BLOCK}""",
"import": f"""zoxide-import {VERSION}
{AUTHOR}
{URL}

Import entries from another application

Usage:
  executable import [OPTIONS] --from <FROM> <PATH>

Arguments:
  <PATH>  

Options:
      --from <FROM>  Application to import from [possible values: autojump, z]
      --merge        Merge into existing database
  -h, --help         Print help
  -V, --version      Print version

{ENV_BLOCK}""",
"init": f"""zoxide-init {VERSION}
{AUTHOR}
{URL}

Generate shell configuration

Usage:
  executable init [OPTIONS] <SHELL>

Arguments:
  <SHELL>  [possible values: bash, elvish, fish, nushell, posix, powershell, tcsh, xonsh, zsh]

Options:
      --no-cmd       Prevents zoxide from defining the `z` and `zi` commands
      --cmd <CMD>    Changes the prefix of the `z` and `zi` commands [default: z]
      --hook <HOOK>  Changes how often zoxide increments a directory's score [default: pwd] [possible values: none, prompt, pwd]
  -h, --help         Print help
  -V, --version      Print version

{ENV_BLOCK}""",
"query": f"""zoxide-query {VERSION}
{AUTHOR}
{URL}

Search for a directory in the database

Usage:
  executable query [OPTIONS] [KEYWORDS]...

Arguments:
  [KEYWORDS]...  

Options:
  -a, --all              Show unavailable directories
  -i, --interactive      Use interactive selection
  -l, --list             List all matching directories
  -s, --score            Print score with results
      --exclude <path>   Exclude the current directory
      --base-dir <path>  Only search within this directory
  -h, --help             Print help
  -V, --version          Print version

{ENV_BLOCK}""",
"remove": f"""zoxide-remove {VERSION}
{AUTHOR}
{URL}

Remove a directory from the database

Usage:
  executable remove [PATHS]...

Arguments:
  [PATHS]...  

Options:
  -h, --help     Print help
  -V, --version  Print version

{ENV_BLOCK}""",
}


def out(s="", end="\n"):
    sys.stdout.write(str(s) + end)


def err(s="", end="\n"):
    sys.stderr.write(str(s) + end)


def clap_error(msg, usage=None, tip=None, status=2):
    err(f"error: {msg}")
    if tip:
        err("")
        err(f"  tip: {tip}")
    if usage:
        err("")
        err(f"Usage: {usage}")
    err("")
    err("For more information, try '--help'.")
    return status


def data_dir():
    d = os.environ.get("_ZO_DATA_DIR")
    if d:
        return Path(d)
    xdg = os.environ.get("XDG_DATA_HOME")
    if xdg:
        return Path(xdg) / "zoxide"
    home = os.environ.get("HOME") or str(Path.home())
    return Path(home) / ".local" / "share" / "zoxide"


def db_path():
    return data_dir() / "db.zo"


def read_db():
    p = db_path()
    if not p.exists():
        return []
    try:
        b = p.read_bytes()
        if len(b) < 12:
            return []
        ver = struct.unpack_from("<I", b, 0)[0]
        if ver != DB_VERSION:
            return []
        n = struct.unpack_from("<Q", b, 4)[0]
        off = 12
        entries = []
        for _ in range(n):
            if off + 8 > len(b): break
            l = struct.unpack_from("<Q", b, off)[0]; off += 8
            path = b[off:off+l].decode("utf-8", "surrogateescape"); off += l
            score = struct.unpack_from("<d", b, off)[0]; off += 8
            ts = struct.unpack_from("<q", b, off)[0]; off += 8
            entries.append({"path": path, "score": score, "time": ts})
        return entries
    except Exception:
        return []


def write_db(entries):
    p = db_path()
    p.parent.mkdir(parents=True, exist_ok=True)
    b = bytearray(struct.pack("<IQ", DB_VERSION, len(entries)))
    for e in entries:
        pb = e["path"].encode("utf-8", "surrogateescape")
        b += struct.pack("<Q", len(pb))
        b += pb
        b += struct.pack("<dq", float(e["score"]), int(e["time"]))
    tmp = p.with_suffix(p.suffix + ".tmp")
    tmp.write_bytes(bytes(b))
    os.replace(tmp, p)


def norm_existing_path(path, resolve=None):
    if resolve is None:
        resolve = os.environ.get("_ZO_RESOLVE_SYMLINKS") == "1"
    if resolve:
        return os.path.realpath(path)
    return os.path.abspath(path)


def normalize_for_remove(path):
    # zoxide canonicalizes paths that currently exist; otherwise it uses the
    # spelling supplied by the user (except absolute paths are already absolute).
    if os.path.isdir(path):
        return norm_existing_path(path)
    return path


def excluded(path):
    spec = os.environ.get("_ZO_EXCLUDE_DIRS")
    if spec is None:
        home = os.environ.get("HOME")
        spec = home or ""
    if spec == "":
        return False
    for pat in spec.split(":"):
        if not pat:
            continue
        if fnmatch.fnmatch(path, pat):
            return True
    return False


def apply_aging(entries):
    try:
        maxage = float(os.environ.get("_ZO_MAXAGE", "10000"))
    except Exception:
        maxage = 10000.0
    if not math.isfinite(maxage) or maxage <= 0:
        return entries
    total = sum(e["score"] for e in entries)
    try:
        over = total > maxage
    except Exception:
        over = False
    if over:
        factor = 0.9 * maxage / total
        new = []
        for e in entries:
            e = dict(e)
            e["score"] = e["score"] * factor
            # zoxide prunes entries that have aged below 1, except an exact zero
            # is kept if a user explicitly created it.
            if e["score"] >= 1.0 or e["score"] == 0.0:
                new.append(e)
        return new
    return entries


def frecency(entry, now=None):
    if now is None:
        now = int(time.time())
    age = now - int(entry.get("time", 0))
    score = float(entry.get("score", 0.0))
    if age < 3600:
        mul = 4.0
    elif age < 86400:
        mul = 2.0
    elif age < 604800:
        mul = 0.5
    else:
        mul = 0.25
    val = score * mul
    if math.isnan(val):
        return float("nan")
    if val > 9999.0:
        val = 9999.0
    return val


def fmt_score(v):
    if math.isnan(v):
        return "   NaN"
    return f"{v:6.1f}"


def sorted_matches(entries):
    now = int(time.time())
    enum = list(enumerate(entries))
    # Descending frecency, then most recently inserted first. Python cannot sort
    # NaN usefully; place it first like Rust's partial comparison fallback does
    # in the common inf-aging case.
    def key(pair):
        i, e = pair
        f = frecency(e, now)
        nan = math.isnan(f)
        return (0 if nan else -f, -i)
    enum.sort(key=key)
    return [e for i, e in enum]


def path_available(p):
    return os.path.isdir(p)


def matches_keywords(path, keywords):
    if not keywords:
        return True
    s = path.lower()
    basename_start = s.rfind('/') + 1
    pos = 0
    for idx, kw in enumerate(keywords):
        k = kw.lower()
        if k == "":
            continue
        is_last = (idx == len(keywords) - 1)
        start = pos
        if is_last and '/' not in k:
            start = max(start, basename_start)
        found = s.find(k, start)
        if found < 0:
            return False
        pos = found + len(k)
    return True


def filter_entries(entries, keywords=None, all_entries=False, exclude=None, base_dir=None):
    keywords = keywords or []
    res = []
    ex_norm = None
    if exclude:
        ex_norm = norm_existing_path(exclude) if os.path.isdir(exclude) else exclude
    base_norm = None
    if base_dir:
        base_norm = norm_existing_path(base_dir) if os.path.isdir(base_dir) else os.path.abspath(base_dir)
        base_norm = base_norm.rstrip('/')
    for e in entries:
        p = e["path"]
        if not all_entries and not path_available(p):
            continue
        if ex_norm:
            ex = ex_norm.rstrip('/')
            if p == ex or p.startswith(ex + '/'):
                continue
        if base_norm:
            if not (p == base_norm or p.startswith(base_norm + '/')):
                continue
        if matches_keywords(p, keywords):
            res.append(e)
    return sorted_matches(res)


def print_entries(entries, with_score=False, nul=False):
    for e in entries:
        if with_score:
            line = f"{fmt_score(frecency(e))}\t{e['path']}" if nul else f"{fmt_score(frecency(e))} {e['path']}"
        else:
            line = e["path"]
        if nul:
            sys.stdout.write(line + "\0")
        else:
            out(line)


def parse_float(s):
    # Rust accepts inf and NaN spellings through lexical-core/standard parsing.
    sl = s.lower()
    if sl in ("nan", "+nan", "-nan"):
        return float("nan")
    if sl in ("inf", "+inf", "infinity", "+infinity"):
        return float("inf")
    if sl in ("-inf", "-infinity"):
        return float("-inf")
    return float(s)


def cmd_add(args):
    if args in (["--help"], ["-h"]): out(HELP["add"]); return 0
    if args in (["--version"], ["-V"]): out(f"zoxide-add {VERSION}"); return 0
    score = 1.0
    paths = []
    i = 0
    stop = False
    while i < len(args):
        a = args[i]
        if not stop and a == "--":
            stop = True; i += 1; continue
        if not stop and a in ("-h", "--help"):
            out(HELP["add"]); return 0
        if not stop and a in ("-V", "--version"):
            out(f"zoxide-add {VERSION}"); return 0
        if not stop and (a == "-s" or a == "--score"):
            if i + 1 >= len(args):
                return clap_error("a value is required for '--score <SCORE>' but none was supplied", "executable add [OPTIONS] <PATHS>...")
            val = args[i+1]
            if val.startswith('-') and val not in ("-inf", "-infinity"):
                return clap_error(f"unexpected argument '{val}' found", "executable add [OPTIONS] <PATHS>...", f"to pass '{val}' as a value, use '-- {val}'")
            try: score = parse_float(val)
            except Exception:
                return clap_error(f"invalid value '{val}' for '--score <SCORE>': invalid float literal")
            i += 2; continue
        if not stop and a.startswith("--score="):
            val = a.split("=",1)[1]
            try: score = parse_float(val)
            except Exception:
                return clap_error(f"invalid value '{val}' for '--score <SCORE>': invalid float literal")
            i += 1; continue
        if not stop and a.startswith('-'):
            return clap_error(f"unexpected argument '{a}' found", "executable add [OPTIONS] <PATHS>...")
        paths.append(a); i += 1
    if not paths:
        return clap_error("the following required arguments were not provided:\n  <PATHS>...", "executable add <PATHS>...")
    normed = []
    for p in paths:
        if not os.path.isdir(p):
            err(f"zoxide: not a directory: {p}")
            return 1
        np = norm_existing_path(p)
        if not excluded(np):
            normed.append(np)
    if not normed:
        return 0
    entries = read_db()
    now = int(time.time())
    by_path = {e["path"]: e for e in entries}
    for p in normed:
        if p in by_path:
            by_path[p]["score"] = float(by_path[p]["score"]) + score
            by_path[p]["time"] = now
        else:
            e = {"path": p, "score": score, "time": now}
            entries.append(e); by_path[p] = e
    entries = apply_aging(entries)
    write_db(entries)
    return 0


def cmd_remove(args):
    if args in (["--help"], ["-h"]): out(HELP["remove"]); return 0
    if args in (["--version"], ["-V"]): out(f"zoxide-remove {VERSION}"); return 0
    paths = []
    stop = False
    for a in args:
        if not stop and a == "--": stop = True; continue
        if not stop and a in ("-h", "--help"): out(HELP["remove"]); return 0
        if not stop and a in ("-V", "--version"): out(f"zoxide-remove {VERSION}"); return 0
        if not stop and a.startswith('-'):
            return clap_error(f"unexpected argument '{a}' found", "executable remove [PATHS]...")
        paths.append(a)
    if not paths:
        return 0
    entries = read_db()
    dbset = {e["path"] for e in entries}
    normed = [normalize_for_remove(p) for p in paths]
    for orig, p in zip(paths, normed):
        if p not in dbset:
            err(f"zoxide: path not found in database: {p}")
            return 1
    entries = [e for e in entries if e["path"] not in set(normed)]
    write_db(entries)
    return 0


def parse_query_args(args):
    opts = {"all": False, "interactive": False, "list": False, "score": False, "exclude": None, "base_dir": None, "keywords": []}
    i = 0; stop = False
    while i < len(args):
        a = args[i]
        if not stop and a == "--": stop = True; i += 1; continue
        if not stop and a in ("-h", "--help"): return "help", opts
        if not stop and a in ("-V", "--version"): return "version", opts
        if not stop and a.startswith('--exclude'):
            if a == '--exclude':
                if i+1 >= len(args): return ("error", "a value is required for '--exclude <path>' but none was supplied"), opts
                opts["exclude"] = args[i+1]; i += 2; continue
            elif a.startswith('--exclude='):
                opts["exclude"] = a.split('=',1)[1]; i += 1; continue
        if not stop and a.startswith('--base-dir'):
            if a == '--base-dir':
                if i+1 >= len(args): return ("error", "a value is required for '--base-dir <path>' but none was supplied"), opts
                opts["base_dir"] = args[i+1]; i += 2; continue
            elif a.startswith('--base-dir='):
                opts["base_dir"] = a.split('=',1)[1]; i += 1; continue
        if not stop and a in ('--all','--interactive','--list','--score'):
            opts[{"--all":"all","--interactive":"interactive","--list":"list","--score":"score"}[a]] = True; i += 1; continue
        if not stop and a.startswith('-') and len(a) > 1:
            ok = True
            for c in a[1:]:
                if c == 'a': opts['all'] = True
                elif c == 'i': opts['interactive'] = True
                elif c == 'l': opts['list'] = True
                elif c == 's': opts['score'] = True
                else: ok = False; break
            if ok:
                i += 1; continue
            return ("badarg", a), opts
        opts["keywords"].append(a); i += 1
    return "ok", opts


def cmd_query(args):
    parsed, opts = parse_query_args(args)
    if parsed == "help": out(HELP["query"]); return 0
    if parsed == "version": out(f"zoxide-query {VERSION}"); return 0
    if isinstance(parsed, tuple) and parsed[0] == "badarg":
        a = parsed[1]
        tip = "a similar argument exists: '--base-dir'" if a.startswith('--b') or a == '--bad' else None
        return clap_error(f"unexpected argument '{a}' found", "executable query --base-dir <path> [KEYWORDS]..." if tip else "executable query [OPTIONS] [KEYWORDS]...", tip)
    if isinstance(parsed, tuple) and parsed[0] == "error":
        return clap_error(parsed[1], "executable query [OPTIONS] [KEYWORDS]...")
    entries = filter_entries(read_db(), opts["keywords"], opts["all"], opts["exclude"], opts["base_dir"])
    if opts["interactive"]:
        return interactive_query(entries, opts["score"])
    if opts["list"]:
        print_entries(entries, opts["score"])
        return 0
    if not entries:
        err("zoxide: no match found")
        return 1
    e = entries[0]
    if opts["score"]:
        out(f"{fmt_score(frecency(e))} {e['path']}")
    else:
        out(e["path"])
    return 0


def interactive_query(entries, with_score_flag=False):
    if shutil.which("fzf") is None:
        err("zoxide: could not find fzf, is it installed?")
        return 1
    data = "".join(f"{fmt_score(frecency(e))}\t{e['path']}\0" for e in entries)
    try:
        proc = subprocess.run(["fzf", "--delimiter=\t", "--nth=2", "--read0"], input=data.encode(), stdout=subprocess.PIPE)
    except FileNotFoundError:
        err("zoxide: could not find fzf, is it installed?")
        return 1
    if proc.returncode != 0 or not proc.stdout:
        err("zoxide: could not read selection from fzf")
        return 1
    sel = proc.stdout.decode("utf-8", "surrogateescape")
    if "\t" in sel:
        path = sel.split("\t", 1)[1]
    else:
        path = sel[7:] if len(sel) >= 7 else ""
    path = path.rstrip("\n\0")
    sys.stdout.write(path)
    if sel.endswith("\n"):
        sys.stdout.write("\n")
    return 0


def cmd_import(args):
    if args in (["--help"], ["-h"]): out(HELP["import"]); return 0
    if args in (["--version"], ["-V"]): out(f"zoxide-import {VERSION}"); return 0
    fmt = None; merge = False; paths = []
    i=0; stop=False
    while i < len(args):
        a=args[i]
        if not stop and a == '--': stop=True; i+=1; continue
        if not stop and a in ('-h','--help'): out(HELP['import']); return 0
        if not stop and a in ('-V','--version'): out(f"zoxide-import {VERSION}"); return 0
        if not stop and a == '--merge': merge=True; i+=1; continue
        if not stop and (a == '--from' or a.startswith('--from=')):
            if a == '--from':
                if i+1 >= len(args): return clap_error("a value is required for '--from <FROM>' but none was supplied", "executable import [OPTIONS] --from <FROM> <PATH>")
                fmt=args[i+1]; i+=2
            else:
                fmt=a.split('=',1)[1]; i+=1
            continue
        if not stop and a.startswith('-'):
            return clap_error(f"unexpected argument '{a}' found", "executable import [OPTIONS] --from <FROM> <PATH>")
        paths.append(a); i+=1
    if fmt is None:
        return clap_error("the following required arguments were not provided:\n  --from <FROM>", "executable import --from <FROM> <PATH>")
    if fmt not in IMPORTS:
        return clap_error(f"invalid value '{fmt}' for '--from <FROM>'\n  [possible values: autojump, z]")
    if not paths:
        return clap_error("the following required arguments were not provided:\n  <PATH>", "executable import --from <FROM> <PATH>")
    if len(paths) > 1:
        return clap_error(f"unexpected argument '{paths[1]}' found", "executable import [OPTIONS] --from <FROM> <PATH>")
    if read_db() and not merge:
        err("zoxide: current database is not empty, specify --merge to continue anyway")
        return 1
    try:
        text = Path(paths[0]).read_text()
    except OSError as e:
        err(f"zoxide: could not open database for importing: {paths[0]}")
        err("")
        err("Caused by:")
        err(f"    {e.strerror} (os error {e.errno})")
        return 1
    try:
        imported = parse_import(fmt, text)
    except Exception as e:
        err("zoxide: import error")
        err("")
        err("Caused by:")
        for line in str(e).split('\n'):
            err("    " + line)
        return 1
    entries = read_db() if merge else []
    by = {e['path']: e for e in entries}
    for e in imported:
        if e['path'] in by:
            by[e['path']]['score'] += e['score']; by[e['path']]['time'] = max(by[e['path']]['time'], e['time'])
        else:
            entries.append(e); by[e['path']] = e
    entries = apply_aging(entries)
    write_db(entries)
    return 0


def parse_import(fmt, text):
    entries=[]
    if fmt == 'z':
        for line in text.splitlines():
            if not line: continue
            parts=line.split('|')
            if len(parts) < 3:
                raise Exception(f"0: invalid epoch: {line}\n1: invalid digit found in string")
            path, rank_s, epoch_s = parts[0], parts[1], parts[2]
            try: rank=parse_float(rank_s)
            except Exception: raise Exception(f"0: invalid rank: {rank_s}\n1: invalid float literal")
            try: epoch=int(epoch_s)
            except Exception: raise Exception(f"0: invalid epoch: {epoch_s}\n1: invalid digit found in string")
            entries.append({'path': path, 'score': rank, 'time': epoch})
    else:
        raw=[]
        for line in text.splitlines():
            if not line: continue
            parts=line.split('\t')
            if len(parts) != 2:
                raise Exception(f"invalid entry: {line}")
            try: rank=parse_float(parts[0])
            except Exception: raise Exception(f"0: invalid rank: {parts[0]}\n1: invalid float literal")
            raw.append((rank, parts[1]))
        if raw:
            # autojump ranks are normalized by the original importer; this
            # smooth logistic-like mapping is close and keeps all entries small.
            mx=max(r for r,p in raw) or 1.0
            for r,p in raw:
                score = 1.0 - math.exp(-float(r)/max(mx/5.0, 1e-9))
                entries.append({'path': p, 'score': score, 'time': 0})
    return entries


def template_dir():
    here = Path(__file__).resolve().parent
    for d in [here / "templates", here.parent / "templates", Path.cwd() / "templates"]:
        if d.exists(): return d
    return Path("templates")


def read_template(name):
    p = template_dir() / name
    try: return p.read_text()
    except Exception: return None


def tweak_init_template(text, shell, cmd, no_cmd, hook):
    # Environment-dependent generated snippets.
    if os.environ.get('_ZO_RESOLVE_SYMLINKS') == '1':
        text = text.replace('\\builtin pwd -L', '\\builtin pwd -P')
        text = text.replace('pwd -L', 'pwd -P')
        text = text.replace('$PWD', '$(pwd -P)') if shell == 'posix' else text
    if os.environ.get('_ZO_ECHO') == '1':
        text = text.replace('\\builtin cd -- "$@"\n}', '\\builtin cd -- "$@" && __zoxide_pwd\n}')
        text = text.replace('builtin cd -- "$@"\n}', 'builtin cd -- "$@" && __zoxide_pwd\n}')
    if shell == 'bash' and cmd == 'z' and not no_cmd and hook in ('pwd','prompt','none'):
        # exact observed variants are bundled for common hook choices
        pass
    if no_cmd:
        if shell == 'bash':
            marker = "# Commands for zoxide. Disable these using --no-cmd.\n#\n\n"
            idx = text.find(marker)
            tail_marker = "# =============================================================================\n#\n# To initialize zoxide"
            j = text.find(tail_marker)
            if idx >= 0 and j >= 0:
                text = text[:idx+len(marker)] + "# -- not configured --\n\n" + text[j:]
        else:
            # Remove the obvious alias/function command block for non-bash shells.
            text = text.replace('alias z __zoxide_z\nalias zi __zoxide_zi', '# -- not configured --')
    if cmd != 'z':
        # Conservative command-name substitutions for generated aliases and completions.
        repls = [
            ('unalias z ', f'unalias {cmd} '), ('function z()', f'function {cmd}()'),
            ('unalias zi ', f'unalias {cmd}i '), ('function zi()', f'function {cmd}i()'),
            ('alias z __zoxide_z', f'alias {cmd} __zoxide_z'), ('alias zi __zoxide_zi', f'alias {cmd}i __zoxide_zi'),
            ('aliases["z"]', f'aliases["{cmd}"]'), ('aliases["zi"]', f'aliases["{cmd}i"]'),
            ('READLINE_LINE="z ', f'READLINE_LINE="{cmd} '),
            ('-- z\n', f'-- {cmd}\n'), ('-r zi ', f'-r {cmd}i '),
            ('complete __zoxide_z -c z ', f'complete __zoxide_z -c {cmd} '),
            ('function z ', f'function {cmd} '), ('function zi ', f'function {cmd}i '),
        ]
        for a,b in repls: text = text.replace(a,b)
    return text


def generated_minimal_init(shell, cmd='z', no_cmd=False, hook='pwd'):
    # Fallback for unusual combinations. It is functional rather than exhaustive.
    if shell in ('bash','zsh','posix'):
        cdi = ' && __zoxide_pwd' if os.environ.get('_ZO_ECHO') == '1' else ''
        pwdflag = '-P' if os.environ.get('_ZO_RESOLVE_SYMLINKS') == '1' else '-L'
        lines = [f"# shellcheck shell={shell if shell!='zsh' else 'bash'}", "", "function __zoxide_pwd() {", f"    \\builtin pwd {pwdflag}", "}", "", "function __zoxide_cd() {", f"    \\builtin cd -- \"$@\"{cdi}", "}", ""]
        if hook != 'none':
            if hook == 'prompt':
                lines += ["function __zoxide_hook() {", "    \\command zoxide add -- \"$(__zoxide_pwd)\"", "}"]
            else:
                lines += ["__zoxide_oldpwd=\"$(__zoxide_pwd)\"", "function __zoxide_hook() {", "    pwd_tmp=\"$(__zoxide_pwd)\"", "    if [ \"${__zoxide_oldpwd}\" != \"${pwd_tmp}\" ]; then __zoxide_oldpwd=\"${pwd_tmp}\"; \\command zoxide add -- \"${pwd_tmp}\"; fi", "}"]
        lines += ["function __zoxide_z() {", "    if [ $# -eq 0 ]; then __zoxide_cd ~; elif [ $# -eq 1 ] && [ -d \"$1\" ]; then __zoxide_cd \"$1\"; else result=\"$(\\command zoxide query --exclude \"$(__zoxide_pwd)\" -- \"$@\")\" && __zoxide_cd \"$result\"; fi", "}", "function __zoxide_zi() { result=\"$(\\command zoxide query -i -- \"$@\")\" && __zoxide_cd \"$result\"; }"]
        if not no_cmd:
            lines += [f"alias {cmd}=__zoxide_z", f"alias {cmd}i=__zoxide_zi"]
        return "\n".join(lines) + "\n"
    return f"# zoxide initialization for {shell}\n# generated by zoxide\n"


def cmd_init(args):
    if args in (["--help"], ["-h"]): out(HELP["init"]); return 0
    if args in (["--version"], ["-V"]): out(f"zoxide-init {VERSION}"); return 0
    cmd = 'z'; no_cmd=False; hook='pwd'; shell=None
    i=0; stop=False
    while i < len(args):
        a=args[i]
        if not stop and a == '--': stop=True; i+=1; continue
        if not stop and a in ('-h','--help'): out(HELP['init']); return 0
        if not stop and a in ('-V','--version'): out(f"zoxide-init {VERSION}"); return 0
        if not stop and a == '--no-cmd': no_cmd=True; i+=1; continue
        if not stop and (a == '--cmd' or a.startswith('--cmd=')):
            if a == '--cmd':
                if i+1 >= len(args): return clap_error("a value is required for '--cmd <CMD>' but none was supplied", "executable init [OPTIONS] <SHELL>")
                cmd=args[i+1]; i+=2
            else:
                cmd=a.split('=',1)[1]; i+=1
            continue
        if not stop and (a == '--hook' or a.startswith('--hook=')):
            if a == '--hook':
                if i+1 >= len(args): return clap_error("a value is required for '--hook <HOOK>' but none was supplied", "executable init [OPTIONS] <SHELL>")
                hook=args[i+1]; i+=2
            else:
                hook=a.split('=',1)[1]; i+=1
            continue
        if not stop and a.startswith('-'):
            return clap_error(f"unexpected argument '{a}' found", "executable init <SHELL>", f"to pass '{a}' as a value, use '-- {a}'")
        if shell is None: shell=a
        else: return clap_error(f"unexpected argument '{a}' found", "executable init <SHELL>")
        i+=1
    if shell is None:
        return clap_error("the following required arguments were not provided:\n  <SHELL>", "executable init [OPTIONS] <SHELL>")
    if shell not in SHELLS:
        tip = "\n\n  tip: a similar value exists: 'bash'" if shell.startswith('bad') else ""
        return clap_error(f"invalid value '{shell}' for '<SHELL>'\n  [possible values: bash, elvish, fish, nushell, posix, powershell, tcsh, xonsh, zsh]{tip}")
    if hook not in HOOKS:
        return clap_error(f"invalid value '{hook}' for '--hook <HOOK>'\n  [possible values: none, prompt, pwd]")
    name = shell
    if shell == 'bash' and cmd == 'z' and not no_cmd and hook == 'none': name = 'bash__hook_none'
    elif shell == 'bash' and cmd == 'z' and not no_cmd and hook == 'prompt': name = 'bash__hook_prompt'
    elif shell == 'bash' and cmd == 'z' and no_cmd and hook == 'pwd': name = 'bash__no_cmd'
    text = read_template(name)
    if text is None:
        text = generated_minimal_init(shell, cmd, no_cmd, hook)
    else:
        text = tweak_init_template(text, shell, cmd, no_cmd, hook)
    sys.stdout.write(text)
    return 0


def edit_reload(nul=True):
    entries = filter_entries(read_db(), [], True, None, None)
    print_entries(entries, True, nul=nul)


def cmd_edit(args):
    if args in (["--help"], ["-h"]): out(HELP["edit"]); return 0
    if args in (["--version"], ["-V"]): out(f"zoxide-edit {VERSION}"); return 0
    if args:
        action=args[0]
        if action == 'reload' and len(args)==1:
            edit_reload(True); return 0
        if action in ('delete','increment','decrement'):
            targets=args[1:]
            entries=read_db()
            if action == 'delete':
                entries=[e for e in entries if e['path'] not in targets]
            else:
                now=int(time.time())
                by={e['path']: e for e in entries}
                for p in targets:
                    if p in by:
                        by[p]['score'] += 1.0 if action=='increment' else -1.0
                        by[p]['time'] = now
                    elif action=='increment':
                        entries.append({'path': p, 'score': 1.0, 'time': now})
                entries=[e for e in entries if e['score'] > 0]
            write_db(entries); edit_reload(True); return 0
        return clap_error(f"unrecognized subcommand '{action}'", "executable edit")
    if shutil.which('fzf') is None:
        err('zoxide: could not find fzf, is it installed?')
        return 1
    bind = 'btab:up,ctrl-r:reload(zoxide edit reload),ctrl-d:reload(zoxide edit delete {2..}),ctrl-w:reload(zoxide edit increment {2..}),ctrl-s:reload(zoxide edit decrement {2..}),ctrl-z:ignore,double-click:ignore,enter:abort,start:reload(zoxide edit reload),tab:down'
    header = 'ctrl-r:reload   \tctrl-d:delete\nctrl-w:increment\tctrl-s:decrement\n\n SCORE\tPATH'
    args_fzf = ['fzf','--delimiter=\t','--nth=2','--read0','--exact','--no-sort',f'--bind={bind}','--cycle','--keep-right','--border=sharp','--border-label=  zoxide-edit  ',f'--header={header}','--info=inline','--layout=reverse','--padding=1,0,0,0','--color=label:bold','--tabstop=1','--preview=\\command -p ls -Cp --color=always --group-directories-first {2..}','--preview-window=down,30%,sharp']
    try:
        subprocess.run(args_fzf, input=b'')
    except FileNotFoundError:
        err('zoxide: could not find fzf, is it installed?')
        return 1
    return 0


def main(argv):
    if not argv:
        out(MAIN_HELP); return 2
    if argv[0] in ('-h','--help'):
        out(MAIN_HELP); return 0
    if argv[0] in ('-V','--version'):
        out(f"zoxide {VERSION}"); return 0
    cmd=argv[0]; args=argv[1:]
    if cmd == 'add': return cmd_add(args)
    if cmd == 'remove': return cmd_remove(args)
    if cmd == 'query': return cmd_query(args)
    if cmd == 'import': return cmd_import(args)
    if cmd == 'init': return cmd_init(args)
    if cmd == 'edit': return cmd_edit(args)
    return clap_error(f"unrecognized subcommand '{cmd}'", "executable <COMMAND>")

if __name__ == '__main__':
    try:
        sys.exit(main(sys.argv[1:]))
    except BrokenPipeError:
        try: sys.stdout.close()
        except Exception: pass
        sys.exit(0)
